_BLANK = re.compile(r"\{([^{}]+)\}")

FIB_ITEMS = []
for idx, (title, marked) in enumerate(FIB_RAW, 1):
    answers = _BLANK.findall(marked)
    assert len(answers) == 3, f"FIB {idx}: expected 3 blanks, got {answers}"
    counter = iter(range(1, 4))
    passage = _BLANK.sub(lambda m: f"[[b{next(counter)}]]", marked)
    transcript = _BLANK.sub(lambda m: m.group(1), marked)
    FIB_ITEMS.append({
        "id": f"q-pl90-fib-{idx:02d}",
        "type_id": "pte-listening-fib",
        "type_name": "Listening Fill in the Blanks",
        "title": title,
        "prompt": "You will hear a recording. Type the missing words in each blank.",
        "context_passage": passage,
        "audio_transcript": transcript,
        "blanks": [{"id": f"b{n}", "correctAnswer": a} for n, a in enumerate(answers, 1)],
        "correct_answers": None,
        "options": None,
        "time_limit_seconds": 120,
        "prep_time_seconds": 7,
        "points": 3,
        "explanation": "The recording says: " + ", ".join(answers) + ".",
    })
